    void SaveProfile(Profile profile) { Directory.CreateDirectory(Path.Combine(root, "profiles")); File.WriteAllText(Path.Combine(root, "profiles", profile.id + ".json"), ProfileJson().Serialize(profile)); }
    void EnsureSession() { if (selected == null) throw new InvalidOperationException("Open a trainer first."); if (session == null || !session.Connected || sessionProfile != selected.id) throw new InvalidOperationException("Connect to the game first."); }
    void Connect() { try { StopScripts(); if (session != null) session.Dispose(); session = new MemorySession(selected.process); sessionProfile = selected.id; if (freezeTimer == null) { freezeTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(300) }; freezeTimer.Tick += (s, e) => { if (session == null || !session.Connected || selected == null || sessionProfile != selected.id) return; foreach (var f in selected.cheats.Where(c => c.freeze && c.kind == "value")) { try { session.WriteValue(f.address, f.dataType, f.value); } catch { f.freeze = false; } } TickScripts(); }; freezeTimer.Start(); } Trainer(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter connection"); } }
