        var connect = Button(session != null && session.Connected && sessionProfile == selected.id ? "Connected" : "▶  Connect", () => Connect(), true); connect.HorizontalAlignment = HorizontalAlignment.Right; connect.VerticalAlignment = VerticalAlignment.Bottom; connect.Margin = new Thickness(0, 0, 25, 22); hero.Children.Add(connect);
        var lower = new Grid { Margin = new Thickness(0, 20, 0, 0) }; Grid.SetRow(lower, 1); page.Children.Add(lower); lower.ColumnDefinitions.Add(new ColumnDefinition()); lower.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(22) }); lower.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(270) });
        var left = new StackPanel(); var leftScroll = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; leftScroll.Content = left; lower.Children.Add(leftScroll); var tools = new StackPanel { Orientation = Orientation.Horizontal }; tools.Children.Add(Copy("TRAINER FEATURES", 14, "#E8DCF6")); var add = Button("＋ Add value", () => ValueEditor(null), true); add.Margin = new Thickness(18, 0, 0, 0); add.Height = 32; tools.Children.Add(add); var custom = Button("＋ Custom logic", () => ScriptEditor(null), false); custom.Margin = new Thickness(9, 0, 0, 0); custom.Height = 32; tools.Children.Add(custom); left.Children.Add(tools);
        if (selected.cheats.Count == 0) { var empty = new StackPanel { Margin = new Thickness(20, 30, 20, 30) }; empty.Children.Add(Copy("No mapped values yet", 18, "#F0E8FA")); empty.Children.Add(Copy("Connect to the running game, scan a value, then save it as a feature.", 12, "#9E91AF")); left.Children.Add(Surface(empty, new Thickness(0))); }
        foreach (var group in selected.cheats.GroupBy(f => String.IsNullOrWhiteSpace(f.category) ? "Player" : f.category))
