                var row = new Grid { Height = 58, Margin = new Thickness(0, 5, 0, 0) }; row.ColumnDefinitions.Add(new ColumnDefinition()); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(78) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(72) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(66) });
                var label = new StackPanel { VerticalAlignment = VerticalAlignment.Center }; label.Children.Add(Copy(f.name ?? "Value", 13, "#EEE7F7")); label.Children.Add(Copy((f.dataType ?? "Int32") + "  ·  " + (f.address ?? "Unmapped"), 10, "#8B809D")); row.Children.Add(label);
                var read = Button("Read", () => { try { EnsureSession(); MessageBox.Show(f.name + ": " + session.ReadValue(f.address, f.dataType), "Current value"); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter"); } }, false); read.Height = 29; read.MinWidth = 0; read.Margin = new Thickness(4); read.Padding = new Thickness(0); read.HorizontalAlignment = HorizontalAlignment.Stretch; Grid.SetColumn(read, 1); row.Children.Add(read);
                var set = Button("Set", () => ValueEditor(f), false); set.Height = 29; set.MinWidth = 0; set.Margin = new Thickness(4); set.Padding = new Thickness(0); set.HorizontalAlignment = HorizontalAlignment.Stretch; Grid.SetColumn(set, 2); row.Children.Add(set);
                var freeze = Button(f.freeze ? "❄ On" : "Freeze", () => { try { EnsureSession(); if (!f.freeze && !AllowWrite(f.name)) return; f.freeze = !f.freeze; if (f.freeze) session.WriteValue(f.address, f.dataType, f.value); SaveProfile(selected); Trainer(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter"); } }, false); freeze.Height = 29; freeze.MinWidth = 0; freeze.Margin = new Thickness(4); freeze.Padding = new Thickness(0); freeze.HorizontalAlignment = HorizontalAlignment.Stretch; Grid.SetColumn(freeze, 3); row.Children.Add(freeze);
                section.Children.Add(row);
            }
            left.Children.Add(Surface(section, new Thickness(14)));
        }
        var right = new StackPanel(); Grid.SetColumn(right, 2); lower.Children.Add(right); var info = new StackPanel(); info.Children.Add(Copy("Game Info", 15, "#F0E7F9")); info.Children.Add(Copy("Process: " + selected.process, 11, "#A99CB9")); info.Children.Add(Copy("Storage: local profile", 11, "#A99CB9")); info.Children.Add(Copy("Mapped values: " + selected.cheats.Count, 11, "#A99CB9")); var editProcess = Button("Edit process", () => EditProcess(), false); info.Children.Add(editProcess); right.Children.Add(Surface(info, new Thickness(17)));
        var edit = new StackPanel { Margin = new Thickness(0, 16, 0, 0) }; edit.Children.Add(Copy("Build this trainer", 15, "#F0E7F9")); edit.Children.Add(Copy("Scan live values or enter a stable address such as Game.exe+0x1234.", 11, "#A99CB9")); var b = Button("Scan and add value", () => ValueEditor(null), true); edit.Children.Add(b); edit.Children.Add(Button("Customize artwork", () => ArtworkEditor(), false)); edit.Children.Add(Button("Export profile", () => ExportProfile(), false)); right.Children.Add(Surface(edit, new Thickness(17)));
    }
    void ValueEditor(Feature existing)
    {
        if (selected == null) return; var w = new Window { Title = existing == null ? "Add value · Alter" : "Edit value · Alter", Width = 560, Height = 575, MinWidth = 500, MinHeight = 530, Owner = this, WindowStartupLocation = WindowStartupLocation.CenterOwner, Background = Brush("#0B0A1B"), Foreground = Ink };
        StyleDialog(w); var sc = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; w.Content = sc; var p = new StackPanel { Margin = new Thickness(24) }; sc.Content = p; p.Children.Add(Copy("MAP A GAME VALUE", 12, "#B68BEF")); p.Children.Add(Copy("Feature name", 11, "#D7CBEB")); var name = new TextBox { Text = existing == null ? "" : existing.name }; p.Children.Add(name); p.Children.Add(Copy("Category", 11, "#D7CBEB")); var category = new TextBox { Text = existing == null ? "Player" : existing.category }; p.Children.Add(category); p.Children.Add(Copy("Type", 11, "#D7CBEB")); var type = new ComboBox { ItemsSource = new[] { "Int32", "Float", "Double" }, SelectedItem = existing == null ? "Int32" : existing.dataType, Height = 30, Background = Brush("#FFFFFF"), Foreground = Brush("#0B0A1B") }; p.Children.Add(type); p.Children.Add(Copy("Value to set", 11, "#D7CBEB")); var value = new TextBox { Text = existing == null ? "100" : existing.value }; p.Children.Add(value); p.Children.Add(Copy("Address or module+offset", 11, "#D7CBEB")); var address = new TextBox { Text = existing == null ? "" : existing.address }; p.Children.Add(address);
        var scanStatus = Copy("Connect to the game first to scan.", 11, "#9487A6"); scanStatus.Margin = new Thickness(0, 12, 0, 4); p.Children.Add(scanStatus); var results = new ListBox { Height = 100, Background = Brush("#111020"), Foreground = Ink, BorderBrush = Brush("#302344") }; p.Children.Add(results); results.SelectionChanged += (s, e) => { if (results.SelectedItem != null) address.Text = "0x" + ((long)results.SelectedItem).ToString("X"); };
        List<long> hits = null; var scanButtons = new StackPanel { Orientation = Orientation.Horizontal }; var first = Button("First scan", async () => { try { EnsureSession(); scanStatus.Text = "Scanning readable memory…"; string t = (string)type.SelectedItem, v = value.Text; hits = await Task.Run(() => session.FirstScan(t, v)); results.ItemsSource = hits.Take(100).ToList(); scanStatus.Text = hits.Count + " matches. Change the game value, then scan again. Scan addresses may move after restart."; } catch (Exception ex) { scanStatus.Text = ex.Message; } }, false); scanButtons.Children.Add(first); var next = Button("Next scan", async () => { try { EnsureSession(); if (hits == null) throw new InvalidOperationException("Run First scan first."); scanStatus.Text = "Filtering matches…"; string t = (string)type.SelectedItem, v = value.Text; hits = await Task.Run(() => session.NextScan(hits, t, v)); results.ItemsSource = hits.Take(100).ToList(); scanStatus.Text = hits.Count + " matches. Select a result to use its address."; } catch (Exception ex) { scanStatus.Text = ex.Message; } }, false); next.Margin = new Thickness(10, 12, 0, 0); scanButtons.Children.Add(next); p.Children.Add(scanButtons);
        var actions = new StackPanel { Orientation = Orientation.Horizontal }; var save = Button("Save feature", () => { try { if (String.IsNullOrWhiteSpace(name.Text) || String.IsNullOrWhiteSpace(address.Text)) throw new FormatException("Enter a name and address."); MemorySession.Encode((string)type.SelectedItem, value.Text); if (session != null && session.Connected && sessionProfile == selected.id) session.Resolve(address.Text); var f = existing ?? new Feature(); f.name = name.Text.Trim(); f.category = String.IsNullOrWhiteSpace(category.Text) ? "Player" : category.Text.Trim(); f.kind = "value"; f.address = address.Text.Trim(); f.dataType = (string)type.SelectedItem; f.value = value.Text.Trim(); if (existing == null) selected.cheats.Add(f); SaveProfile(selected); w.Close(); Trainer(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Invalid feature"); } }, true); actions.Children.Add(save);
        if (existing != null) { var apply = Button("Write value now", () => { try { EnsureSession(); if (!AllowWrite(name.Text)) return; session.WriteValue(address.Text, (string)type.SelectedItem, value.Text); MessageBox.Show("Value written.", "Alter"); } catch (Exception ex) { MessageBox.Show(ex.Message, "Alter"); } }, false); apply.Margin = new Thickness(10, 12, 0, 0); actions.Children.Add(apply); var remove = Button("Remove", () => { selected.cheats.Remove(existing); SaveProfile(selected); w.Close(); Trainer(); }, false); remove.Margin = new Thickness(10, 12, 0, 0); actions.Children.Add(remove); }
        p.Children.Add(actions); w.ShowDialog();
    }
    void ExportProfile() { if (selected == null) return; var d = new Microsoft.Win32.SaveFileDialog { Filter = "Alter profile|*.json", FileName = selected.name + ".json" }; if (d.ShowDialog() == true) File.WriteAllText(d.FileName, ProfileJson().Serialize(selected)); }
    void EditProcess() { if (selected == null) return; var w = new Window { Title = "Set game process", Width = 420, Height = 230, Owner = this, WindowStartupLocation = WindowStartupLocation.CenterOwner, Background = Brush("#0B0A1B"), Foreground = Ink }; StyleDialog(w); var p = new StackPanel { Margin = new Thickness(22) }; w.Content = p; p.Children.Add(Copy("Executable name", 12, "#D7CBEB")); var input = new TextBox { Text = selected.process }; p.Children.Add(input); p.Children.Add(Copy("Use the exact running process name, such as Game.exe.", 11, "#9588A7")); p.Children.Add(Button("Save process", () => { if (String.IsNullOrWhiteSpace(input.Text)) return; if (session != null) { session.Dispose(); session = null; } selected.process = Path.GetFileName(input.Text.Trim()); SaveProfile(selected); w.Close(); Trainer(); }, true)); w.ShowDialog(); }
    void RemoveProfile(Profile profile) { if (prefs.ConfirmRemovals && MessageBox.Show("Remove " + profile.name + " from this local library?", "Alter", MessageBoxButton.YesNo) != MessageBoxResult.Yes) return; string file = Path.Combine(root, "profiles", profile.id + ".json"); if (File.Exists(file)) File.Delete(file); if (sessionProfile == profile.id && session != null) { StopScripts(); session.Dispose(); session = null; } selected = null; Load(); Library(); }
    void Create() { var w = new Window { Title = "Create local trainer", Width = 420, Height = 300, Owner = this, WindowStartupLocation = WindowStartupLocation.CenterOwner, Background = Brush("#0B0A1B"), Foreground = Ink }; StyleDialog(w); var p = new StackPanel { Margin = new Thickness(22) }; w.Content = p; p.Children.Add(Copy("Game name", 12, "#D7CBEB")); var name = new TextBox(); p.Children.Add(name); p.Children.Add(Copy("Process name (Game.exe)", 12, "#D7CBEB")); var process = new TextBox(); p.Children.Add(process); p.Children.Add(Copy("The trainer stays on this PC until you export its JSON profile.", 11, "#9588A7")); var b = Button("Create trainer", () => { if (String.IsNullOrWhiteSpace(name.Text) || String.IsNullOrWhiteSpace(process.Text)) { MessageBox.Show("Enter the game and process names."); return; } var profile = new Profile { id = Guid.NewGuid().ToString("N"), name = name.Text.Trim(), process = Path.GetFileName(process.Text.Trim()), version = "1" }; SaveProfile(profile); w.Close(); Load(); selected = profiles.FirstOrDefault(x => x.id == profile.id); OpenProfile(selected); }, true); p.Children.Add(b); w.ShowDialog(); }
    void Import() { var d = new Microsoft.Win32.OpenFileDialog { Filter = "Trainer files|*.json;*.ct;*.exe|Alter profile|*.json|Cheat Engine table|*.ct|FLiNG trainer EXE|*.exe" }; if (d.ShowDialog() != true) return; try { Profile profile; if (Path.GetExtension(d.FileName).Equals(".exe", StringComparison.OrdinalIgnoreCase)) { profile = ImportExternalTrainer(d.FileName); } else if (Path.GetExtension(d.FileName).Equals(".ct", StringComparison.OrdinalIgnoreCase)) { profile = ImportTable(d.FileName); MessageBox.Show("Imported " + profile.cheats.Count + " direct address entries. Pointer records and scripts were skipped.", "Alter table import"); } else { profile = ProfileJson().Deserialize<Profile>(File.ReadAllText(d.FileName)); if (profile == null || String.IsNullOrWhiteSpace(profile.name) || String.IsNullOrWhiteSpace(profile.process)) throw new FormatException("This profile needs a game name and process name."); profile.id = Guid.NewGuid().ToString("N"); if (profile.cheats == null) profile.cheats = new List<Feature>(); profile.cheats = profile.cheats.Where(f => f != null && ((f.kind == "value" && !String.IsNullOrWhiteSpace(f.address) && (f.dataType == "Int32" || f.dataType == "Float" || f.dataType == "Double")) || (f.kind == "external" && !String.IsNullOrWhiteSpace(f.hotkey)) || (f.kind == "script" && !String.IsNullOrWhiteSpace(f.name)))).ToList(); foreach (var feature in profile.cheats.Where(f => f.kind == "script")) { feature.id = Guid.NewGuid().ToString("N"); feature.trusted = false; feature.freeze = false; } } SaveProfile(profile); Load(); Library(); } catch (Exception ex) { MessageBox.Show(ex.Message, "Import failed"); } }
    Profile ImportTable(string path) { var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, XmlResolver = null }; XDocument doc; using (var reader = XmlReader.Create(path, settings)) doc = XDocument.Load(reader); var profile = new Profile { id = Guid.NewGuid().ToString("N"), name = Path.GetFileNameWithoutExtension(path), process = "Game.exe", version = "ct-import" }; foreach (var entry in doc.Descendants("CheatEntry")) { if (entry.Element("AssemblerScript") != null || entry.Element("Offsets") != null) continue; string raw = (string)entry.Element("Address"), vt = (string)entry.Element("VariableType"); if (String.IsNullOrWhiteSpace(raw)) continue; string type = vt == "4 Bytes" ? "Int32" : vt == "Float" ? "Float" : vt == "Double" ? "Double" : null; if (type == null) continue; string addr = raw.Trim().Replace("\"", ""); if (addr.Contains("+")) { var parts = addr.Split('+'); if (parts.Length != 2) continue; long n; if (!long.TryParse(parts[1].Replace("0x", ""), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out n)) continue; addr = parts[0] + "+0x" + n.ToString("X"); } else { long n; if (!long.TryParse(addr.Replace("0x", ""), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out n)) continue; addr = "0x" + n.ToString("X"); } profile.cheats.Add(new Feature { name = ((string)entry.Element("Description") ?? "Imported value").Trim('"'), category = "Imported", kind = "value", address = addr, dataType = type, value = "0" }); } return profile; }
